+
+    .eyebrow {
+      display: inline-flex;
+      align-items: center;
+      gap: 10px;
+      width: fit-content;
+      padding: 8px 14px;
+      border: 1px solid rgba(139, 92, 246, 0.28);
+      border-radius: 999px;
+      background: rgba(139, 92, 246, 0.12);
+      color: #c4b5fd;
+      font-size: 0.9rem;
+      letter-spacing: 0.02em;
+    }
+
+    h1 {
+      margin: 0;
+      font-size: clamp(2.4rem, 4vw, 4rem);
+      line-height: 1.05;
+      letter-spacing: -0.04em;
+    }
+
+    .subtitle {
+      max-width: 60ch;
+      margin: 0;
+      color: var(--muted);
+      font-size: 1.05rem;
+    }
+
+    .faq {
+      display: grid;
+      gap: 14px;
+    }
+
+    .example {
+      overflow: hidden;
+      border: 1px solid var(--panel-border);
+      border-radius: 22px;
+      background: linear-gradient(180deg, rgba(24, 33, 61, 0.95), rgba(14, 20, 37, 0.94));
+      box-shadow: var(--shadow);
+      backdrop-filter: blur(16px);
+    }
+
+    .question {
+      width: 100%;
+      padding: 20px 22px;
+      border: 0;
+      background: transparent;
+      color: var(--text);
+      cursor: pointer;
+      display: flex;
+      align-items: center;
+      justify-content: space-between;
+      gap: 18px;
+      text-align: left;
+      font: inherit;
+    }
+
+    .question:focus-visible {
+      outline: 3px solid rgba(139, 92, 246, 0.7);
+      outline-offset: -3px;
+    }
+
+    .question strong {
+      font-size: 1.05rem;
+      letter-spacing: -0.01em;
+    }
+
+    .icon {
+      flex: 0 0 auto;
+      width: 36px;
+      height: 36px;
+      border-radius: 50%;
+      display: grid;
+      place-items: center;
+      background: rgba(139, 92, 246, 0.16);
+      color: #d8c6ff;
+      transition: transform 180ms ease, background 180ms ease;
+    }
+
+    .example[data-open="true"] .icon {
+      transform: rotate(45deg);
+      background: rgba(34, 197, 94, 0.18);
+      color: #b8f2ca;
+    }
+
+    .details {
+      display: grid;
+      grid-template-rows: 0fr;
+      transition: grid-template-rows 220ms ease;
+    }
+
+    .details > div {
+      overflow: hidden;
+    }
+
+    .example[data-open="true"] .details {
+      grid-template-rows: 1fr;
+    }
+
+    .answer {
+      padding: 0 22px 20px;
+      color: var(--muted);
+    }
+
+    .answer p {
+      margin: 0;
+    }
+
+    .answer p + p {
+      margin-top: 10px;
+    }
+
+    @media (max-width: 640px) {
+      .page {
+        width: min(100% - 20px, 920px);
+        padding-top: 28px;
+      }
+
+      .question {
+        padding: 18px 18px;
+      }
+
+      .answer {
+        padding: 0 18px 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main id="app" class="page" aria-label="Cat FAQ"></main>
+
+  <script>
+    const faqData = [
+      {
+        question: "Why do cats purr?",
+        answer: [
+          "Cats purr for comfort, communication, and sometimes even self-soothing. It often means they feel safe, but they may also purr when stressed or recovering."
+        ]
+      },
+      {
+        question: "How much sleep do cats need?",
+        answer: [
+          "Most cats sleep 12 to 16 hours a day, and kittens or senior cats may sleep even more. Their short bursts of energy are part of that classic cat rhythm."
+        ]
+      },
+      {
+        question: "Why do cats knead blankets?",
+        answer: [
+          "Kneading is a comforting behavior learned as kittens. Adult cats often do it when they feel relaxed, affectionate, or ready for a cozy nap."
+        ]
+      },
+      {
+        question: "Should indoor cats be entertained?",
+        answer: [
+          "Yes. Scratching posts, climbing spaces, puzzle feeders, and short play sessions help cats stay mentally and physically healthy."
+        ]
+      }
+    ];
+
+    function FAQItem({ question, answer, index }) {
+      const item = document.createElement("div");
+      item.className = "example";
+      item.dataset.open = "false";
+
+      const button = document.createElement("button");
+      button.className = "question";
+      button.type = "button";
+      button.setAttribute("aria-expanded", "false");
+      button.setAttribute("aria-controls", `answer-${index}`);
+      button.innerHTML = `<strong>${question}</strong><span class="icon" aria-hidden="true">+</span>`;
+
+      const details = document.createElement("div");
+      details.className = "details";
+      details.id = `answer-${index}`;
+      details.hidden = true;
+
+      const inner = document.createElement("div");
+      inner.className = "answer";
+      inner.innerHTML = answer.map((paragraph) => `<p>${paragraph}</p>`).join("");
+
+      details.appendChild(inner);
+
+      button.addEventListener("click", () => {
+        const open = item.dataset.open === "true";
+        item.dataset.open = String(!open);
+        button.setAttribute("aria-expanded", String(!open));
+        details.hidden = open;
+      });
+
+      item.appendChild(button);
+      item.appendChild(details);
+      return item;
+    }
+
+    function App() {
+      const root = document.getElementById("app");
+
+      const hero = document.createElement("section");
+      hero.className = "hero";
+      hero.innerHTML = `
+        <div class="eyebrow">Cat care made simple</div>
+        <h1>Frequently asked cat questions</h1>
+        <p class="subtitle">Quick answers about feline behavior, habits, and the little mysteries that make cats so charming.</p>
+      `;
+
+      const faq = document.createElement("section");
+      faq.className = "faq";
+      faq.setAttribute("aria-label", "Frequently asked questions");
+
+      faqData.forEach((item, index) => {
+        faq.appendChild(FAQItem({ ...item, index }));
+      });
+
+      root.append(hero, faq);
+    }
+
+    App();
+  </script>
+</body>
+</html>
*** End Patch
