      display: grid;
      gap: 14px;
      margin-bottom: 28px;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      width: fit-content;
      padding: 8px 14px;
      border: 1px solid rgba(139, 92, 246, 0.28);
      border-radius: 999px;
      background: rgba(139, 92, 246, 0.12);
      color: #c4b5fd;
      font-size: 0.9rem;
      letter-spacing: 0.02em;
    }

